{
  "name": "opencode-advisor",
  "version": "0.1.0",
  "description": "An opencode plugin that hands the live session transcript to a reasoning model for a second opinion — no Claude Code, no jq, no shell script.",
  "type": "module",
  "main": "src/advisor.ts",
  "exports": {
    ".": "./src/advisor.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "advisor",
    "code-review",
    "second-opinion",
    "reasoning",
    "llm"
  ],
  "license": "MIT",
  "author": "Al Kevin Tan",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alkevintan/opencode-advisor.git"
  },
  "bugs": {
    "url": "https://github.com/alkevintan/opencode-advisor/issues"
  },
  "homepage": "https://github.com/alkevintan/opencode-advisor#readme",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.5"
  }
}
